    update_banner_text: "Hay una nueva versión de PaperGames disponible.",
    update_banner_whats_new: "Novedades: PaperGames ya está disponible en árabe, el nuevo juego «Tutti Frutti» hace de director del juego de palabras con papel y lápiz, y el Xiangqi ahora aplica las reglas del jaque y la persecución perpetuos.",
    update_banner_reload: "Recargar ahora",
